const h = React.createElement;
const cl = {extrapolateLeft:'clamp',extrapolateRight:'clamp'};
const shrinkEnd = Math.floor(durationInFrames * 0.22);
const boardStart = Math.floor(durationInFrames * 0.18);
const barStart = Math.floor(durationInFrames * 0.33);
const stag = Math.max(1, Math.round(0.1 * fps));
const cntStart = barStart + 7 * stag;

const dots = h('div',{style:{position:'absolute',inset:0,backgroundImage:'radial-gradient(circle,'+D.text_dim+' 1px,transparent 1px)',backgroundSize:D.dot_grid_spacing+'px '+D.dot_grid_spacing+'px',opacity:D.dot_grid_opacity}});

const tS = interpolate(frame,[0,shrinkEnd],[1,0.25],cl);
const tL = interpolate(frame,[0,shrinkEnd],[width*0.15,width*0.73],cl);
const tT = interpolate(frame,[0,shrinkEnd],[height*0.35,height*0.04],cl);
const tO = interpolate(frame,[Math.floor(shrinkEnd*0.7),shrinkEnd],[1,0.5],cl);

const miniTrack = h('div',{style:{position:'absolute',left:tL,top:tT,width:width*0.22,transform:'scale('+tS+')',transformOrigin:'top left',opacity:tO,background:D.surface,borderRadius:8,padding:10}},
  [['55%',D.violet],['75%',D.cyan]].map(function(pair,i){
    return h('div',{key:i,style:{position:'relative',height:18,background:D.bg,borderRadius:4,marginBottom:i===0?5:0,overflow:'hidden'}},
      h('div',{style:{position:'absolute',left:0,top:0,bottom:0,width:pair[0],background:pair[1],borderRadius:4,opacity:0.5}}),
      h('div',{style:{position:'absolute',left:pair[0],top:'50%',transform:'translate(-50%,-50%)',width:8,height:8,borderRadius:'50%',background:pair[1],boxShadow:'0 0 6px '+pair[1]}})
    );
  })
);

const bSp = spring({frame:Math.max(0,frame-boardStart),fps,config:{damping:14,stiffness:180}});
const bOp = interpolate(frame,[boardStart,Math.max(boardStart+1,boardStart+8)],[0,1],cl);

const maxSeg = 10;
const bW = width * 0.38;
const sW = bW / maxSeg - 3;

const makeBar = function(label,color,numFilled,wins){
  const segs = Array.from({length:maxSeg},function(_,i){
    if(i >= numFilled) return h('div',{key:i,style:{width:sW,height:34,background:D.bg,borderRadius:3,marginRight:3,border:'1px solid '+D.text_dim,opacity:0.3}});
    const s0 = barStart + i * stag;
    const s1 = Math.max(s0+1,s0+stag);
    const p = interpolate(frame,[s0,s1],[0,1],cl);
    return h('div',{key:i,style:{width:sW,height:34,background:color,borderRadius:3,marginRight:3,opacity:p,transform:'scaleX('+p+')',transformOrigin:'left',boxShadow:p>0.8?'0 0 10px '+color:'none'}});
  });
  const cEnd = Math.max(cntStart+1,cntStart+18);
  const cnt = Math.round(interpolate(frame,[cntStart,cEnd],[0,wins],cl));
  const cSp = spring({frame:Math.max(0,frame-cntStart),fps,config:{damping:12,stiffness:200}});
  return h('div',{style:{display:'flex',alignItems:'center',marginBottom:18}},
    h('div',{style:{width:100,fontFamily:D.font_mono,fontSize:14,fontWeight:700,color:color,textAlign:'right',marginRight:14,letterSpacing:1}},label),
    h('div',{style:{display:'flex',alignItems:'center'}},segs),
    h('div',{style:{marginLeft:16,fontFamily:D.font_display,fontSize:38,fontWeight:900,color:D.white,minWidth:44,textAlign:'center',transform:'scale('+Math.min(cSp,1.1)+')',opacity:interpolate(frame,[cntStart,Math.max(cntStart+1,cntStart+5)],[0,1],cl)}},String(cnt))
  );
};

const board = h('div',{style:{position:'absolute',left:'50%',top:'52%',transform:'translate(-50%,-50%) scale('+bSp+')',opacity:bOp,background:D.surface,borderRadius:14,padding:'30px 40px 26px',border:'1px solid '+D.text_dim,boxShadow:'0 0 50px rgba(0,0,0,0.5)'}},
  h('div',{style:{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:24,paddingBottom:12,borderBottom:'1px solid '+D.text_dim}},
    h('div',{style:{fontFamily:D.font_display,fontSize:22,fontWeight:800,color:D.white,letterSpacing:5,textTransform:'uppercase'}},'SCOREBOARD'),
    h('div',{style:{fontFamily:D.font_mono,fontSize:11,color:D.text_dim,letterSpacing:2}},'WINS')
  ),
  makeBar('GPT-5.5',D.violet,4,4),
  makeBar('CLAUDE',D.cyan,6,6)
);

return h('div',{style:{position:'absolute',inset:0,background:D.bg,overflow:'hidden'}},dots,miniTrack,board);
